-- Modified from ProjectEQ Lua.
-- Source: erudnint/Shondo_Billin.lua
-- P99 audit: Shondo and the Tonic
-- P99 faction deltas: Gem Choppers +10, Merchants of Ak'Anon +2,
-- King Ak'Anon +2, Dark Reflection -2, Clan Grikbar -1.
-- items: 13126

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Oh, Brell!! Help me get out of here. I did nothing wrong!! I did not know you could not take that [tonic] out of the city.");
	elseif(e.message:findi("tonic")) then
		e.self:Say("Oh, why did I have to try and help that Erudite in Qeynos? He was sick and vomiting and needed something called Erud's Tonic!! Now just because I wanted to help, I am going to be vomiting up my insides!! Oh, Brell!!! GET ME OUT OF HERE!!");
	elseif(e.message:findi("where is the heretic")) then
		e.self:Say("Why are you asking me about the heretic?! I am going to die! DO YOU HEAR ME?!! Oh, I need a drink. Please... honor a dying man's last request, a bottle of Vasty Deep Ale. If you get me that, I will tell you what I know of the heretic.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 13126})) then
		e.self:Say("Gulp.. Gulp.. Aaahhh!!! That hits the spot. All I can tell you is that the heretic's name was E'lial B'rook. He mumbled something about a rendezvous and he would be floating down a river, smooth sailing back to something called Paineel. That's all I know.");
		e.other:Ding();
		e.other:Faction(255,10,0); -- Gem Choppers
		e.other:Faction(288,2,0); -- Merchants of Ak`Anon
		e.other:Faction(333,2,0); -- King Ak`Anon
		e.other:Faction(238,-2,0); -- Dark Reflection
		e.other:Faction(1604,-1,0); -- Clan Grikbar
		e.other:AddEXP(100);
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

function event_combat(e)
if e.joined then
eq.spawn2(112047, 0, 0, e.self:GetX(),e.self:GetY(),e.self:GetZ(),0); -- NPC: a_crystalline_shard
eq.depop_with_timer();
end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {gold = 50})) then
		-- Confirmed Live Experience
		e.self:Say("Since you have given me gold, I will give you gloves. For more magic gloves, give a bloodstone to Tarn Visilin in the High Keep library.");
		e.other:QuestReward(e.self,0,0,0,0,2354,1); -- Item: Enchanted Gloves
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

-- Quest by mystic414

-- Quest Name: A job for Nanrum
-- Author: BWStripes
-- Converted to .lua by Speedz
-- Added support for Urako's Big Mistake
-- items: 10307, 10351, 10026, 10060, 10018, 10006, 10017

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Peh! What am you wanted?! I am Basher Nanrum. You? " .. e.other:GetName() .. "? Heh, you look for works? Hmm, me tinks you too weakling for [" .. eq.say_link("job",false,"job") .. "] me need done. Hmm.. You might do, mebbe.");
	elseif(e.message:findi("job")) then
		e.self:Say("Me in charge of making torches for basher patrols. But Nanrum is much too mighty for such stupid job and Nanrum get idea. Dem fire bugses in da desert - dem eyes glowed. And dem don't burneded like torches. If " .. e.other:GetName() .. " getted Nanrum three fire beetle eyes me would giveded " .. e.other:GetName() .. " a shiny thingie dat you wanteded. Go ahed, " .. e.other:GetName() .. " , an' get me da eyes.");
	elseif(e.message:findi("where is the skeleton")) then
		e.self:Say("Yeah!  Me see dat bone man.  He over by da Cleaver.  He tink he a butcher or sumting!");
		eq.unique_spawn(52118,0,0,-459,359,10,0); -- NPC: a_skeleton
	end
end

function event_trade(e)
	local item_lib = require("items");
	if (item_lib.check_turn_in(e.trade, {item1 = 10307, item2 = 10307, item3 = 10307})) then
		e.self:Say("Heh heh. All da eyeballses! I didn't think ya could do it but ya did. Here is da shiny. If you gets more I always have more shinies.");
		e.other:SummonItem(eq.ChooseRandom(10351, 10026, 10060, 10018, 10006, 10017)); -- Item(s): Brass Earring (10351)
		e.other:Faction(235,1,0); -- Da Bashers
		e.other:Faction(222,-1,0); -- Broken Skull Clan
		e.other:Ding();
		e.other:AddEXP(100);
	elseif (item_lib.check_turn_in(e.trade, {item1 = 10307, item2 = 10307})) then
	 	e.self:Say("Well dat be some of da eyeballses I askeded for. But I you needs ta give me three for da shiny.");
		e.other:SummonItem(10307,2); -- Item: Fire Beetle Eye
	elseif (item_lib.check_turn_in(e.trade, {item1 = 10307})) then
	 	e.self:Say("Well dat be some of da eyeballses I askeded for. But I you needs ta give me three for da shiny.");
		e.other:SummonItem(10307); -- Item: Fire Beetle Eye
	end
	item_lib.return_items(e.self, e.other, e.trade)
end

-- Source: erudnext/Leraena_Shelyrak.lua
-- P99 audit: Clear Water, Kobold Shaman Paws and Quellious Symbol Quests.
-- Catman Alliance restored from https://wiki.project1999.com/Catman_Alliance.
-- items: 13989, 18723, 13546, 13883, 15213, 15011, 17090, 14582, 14583, 14585, 1564, 1565, 1566, 1772, 1780, 1781
function event_spawn(e)
	local xloc = e.self:GetX();
	local yloc = e.self:GetY();
	eq.set_proximity(xloc - 50, xloc + 50, yloc - 50, yloc + 50);
end

function event_enter(e)
	if(e.other:HasItem(18723)) then
		e.other:Message(MT.Yellow,"A commanding, yet kind looking Erudite turns towards you as you attempt to get your bearings. 'Do not be startled. I am Leraena Shelyrak, Guild Master for the Clerics of Quellious. Read the note in your inventory and hand it to me when you are ready to begin your training.'");
	end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Welcome, my child. I am Leraena Shelyrak, overseer of the Temple of Divine Light. Inside this temple, you may find the path to inner peace. Introduce yourself to each of the priests and priestesses of the temple as well as the paladins. Help us oppose the [kobold shaman].");
	-- The specific offer must precede the broader matching topic.
	elseif(e.message:findi("slay the kobold shaman")) then
		e.self:Say("Go to Toxxulia Forest and slay the kobold shamans. Bring me three Odd Kobold Paws as proof of your work.");
	-- P99's displayed hint and accepted response use both shaman and shamen.
	-- Match these specific stages before the generic paw-quest topic.
	elseif(e.message:findi("greater kobold shaman") or e.message:findi("greater kobold shamen")) then
		e.self:Say("Collect eight Odd Bronze Necklaces from the greater kobold shamen. Combine them in this sack and return the full sack with your Initiate Symbol of Quellious. You must reach level 20 for this advancement.");
		e.other:SummonItem(17090);
	elseif(e.message:findi("powerful kobold shaman") or e.message:findi("powerful kobold shamen") or e.message:findi("powerful shamen")) then
		e.self:Say("Take this sack to the Warrens. Collect eight Odd Bone Necklaces from the lesser shamen and combine them in the sack, then return it to me.");
		e.other:SummonItem(17090);
	elseif(e.message:findi("ready to advance")) then
		e.self:Say("Bring me the Odd Cold Iron Necklace worn by High Shaman Drogik in the Warrens so we can investigate the source of these powers.");
	elseif(e.message:findi("kobold shaman")) then
		e.self:Say("The kobold shamans have learned to heal their kin. Will you [slay the kobold shaman] for our temple?");
	elseif(e.message:findi("guild coin")) then
		e.self:Say("Yes, of course. Here it is. Remember that it is not a form of currency.");
		e.other:SummonItem(13989); -- Item: Peacekeeper Token
	end
end

function event_trade(e)
	local item_lib = require("items");

	if(item_lib.check_turn_in(e.trade, {item1 = 18723})) then --  Tattered Note
		e.self:Say("Greetings. and welcome to the Temple of Divine Light! Here is your guild tunic. Serve Quellious well.");
		e.other:SummonItem(13546); --  Faded Silver Tunic*
		e.other:Ding();
		e.other:Faction(298,100,0); --  Peace Keepers.
		e.other:Faction(266,25,0); --  High Council of Erudin.
		e.other:Faction(265,-25,0); --  Heretics.
		e.other:AddEXP(100); 
	elseif(item_lib.check_turn_in(e.trade, {item1 = 2049})) then --  rolled up strip of cloth
		e.self:Say("This is important news indeed. It seems there is a tribe of cat men in the Stonebrunt Mountains that wishes to form an alliance with Erudin. I must alert the High Council of this immediately, thank you for your services."); 
		e.other:AddMoneyToPP(9, 0, 0, 0, true);
		e.other:Faction(298,5,0); --  Peace Keepers.
		e.other:Faction(266,5,0); --  High Council of Erudin.
		e.other:Faction(265,-5,0); --  Heretics.
		e.other:AddEXP(1000);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 13883, item2 = 13883, item3 = 13883})) then
		e.self:Say("Fine work. These paws prove your service to our temple. Accept this small reward, then help us investigate the [more powerful kobold shamen].");
		e.other:SummonItem(eq.ChooseRandom(15213, 15011));
		e.other:Ding();
		e.other:Faction(298,20,0);
		e.other:Faction(266,5,0);
		e.other:Faction(265,-5,0);
		-- Retain upstream XP where P99 provides no exact amount. The cached
		-- walkthrough documents a 17-silver payment; use that fixed amount.
		e.other:AddEXP(500);
		e.other:AddMoneyToPP(0,17,0,0);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 14582})) then
		e.self:Say("These markings require further study. Accept the Initiate Symbol of Quellious, and speak to me about the [greater kobold shaman] when you are ready.");
		e.other:SummonItem(1564);
		e.other:Ding();
		-- P99 confirms XP/faction without amounts for this stage. Use the
		-- preceding temple quest's modest reward rather than invent a new scale.
		e.other:Faction(298,20,0);
		e.other:Faction(266,5,0);
		e.other:Faction(265,-5,0);
		e.other:AddEXP(500);
	-- The real level gate must run before check_turn_in consumes anything.
	elseif(e.other:GetLevel() >= 20 and item_lib.check_turn_in(e.trade, {item1 = 14583, item2 = 1564})) then
		e.self:Say("Your service has earned the Disciple Symbol of Quellious. Return when you are [ready to advance].");
		e.other:SummonItem(1565);
		e.other:Ding();
		e.other:Faction(298,30,0);
		e.other:Faction(266,7,0);
		e.other:Faction(265,-7,0);
		e.other:AddEXP(500);
	elseif(item_lib.check_turn_in(e.trade, {item1 = 14585})) then
		e.self:Say("Take this necklace and Sealed Parchment to Glyssa Sonshaw at the Academy of Arcane Science in West Freeport. Return with your findings and Disciple Symbol of Quellious.");
		e.other:SummonItem(14585);
		e.other:SummonItem(1772);
		e.other:Ding();
	elseif(item_lib.check_turn_in(e.trade, {item1 = 1780, item2 = 1781, item3 = 1565})) then
		e.self:Say("Your translations and the doctrine reveal the kobolds' religion. Accept the Regent Symbol of Quellious for your service.");
		e.other:SummonItem(1566);
		e.other:Ding();
		-- P99 gives directions, but not exact values here; retain upstream.
		e.other:Faction(298,20,0);
		e.other:Faction(266,20,0);
		e.other:Faction(265,-20,0);
		e.other:AddEXP(1000);
	end
	item_lib.return_items(e.self, e.other, e.trade);
end

