		e.self:CastSpell(751,e.self:GetID())
	elseif(e.timer=="SpawnGolem") then
		local construct_locs = { 
			[1] = { 189.61, -586.55, -8.55,128}, 
			[2] = { 180.10, -569.03, -8.55,380},
