function event_timer(e)
	if(e.timer == "Phase1Water") then
		-- spawn first wave of 2 a_triloun_gatherer 
		eq.spawn2(eq.ChooseRandom(223092,223093),0,0,48,892,495,371);
		eq.spawn2(eq.ChooseRandom(223092,223093),0,0,48,842,495,371);

		-- Check on which version to spawn
		local expedition = eq.get_expedition()
		if (expedition.valid and not expedition:HasLockout('Anar of Water')) then
			eq.spawn2(223104,0,0,68,867,495,371);	--Anar_of_Water (223104)
		else
			eq.spawn2(223091,0,0,68,867,495,371);	--#Shadow_of_Anar (223091)
		end
		eq.stop_timer("Phase1Water");
	elseif(e.timer == "player_count") then
		CheckPlayerCount(e);
	end
end


function event_signal(e)
	-- signal 1 comes from the phase 1 mobs and is used to increment a
	-- counter so we know when to signal the win
	if (e.signal == 1) then
		event_counter = event_counter + 1;
		-- win on a 7 count
		if (event_counter == 7) then
			-- tell zone_status
			eq.signal(223097,223172); -- Add Loot Lockout for Phase 1 Wing
			eq.signal(223097,2); -- Increment Phase 1 Wing Counter
			eq.local_emote({e.self:GetX(), e.self:GetY(), e.self:GetZ()},MT.LightGray,80,"Ethereal mists gather at the far wall, causing it to fade in and out of focus.");
			-- depop as my job is done.
			eq.depop();
		end
	end
end

function CheckPlayerCount(e)
	local player_list = eq.get_entity_list():GetClientList();
	local count = 0;
	if(player_list ~= nil) then
		for pc in player_list.entries do
			if pc:GetX() >= min_x and pc:GetX() <= max_x and pc:GetY() >= min_y and pc:GetY() <= max_y and not pc:GetGM() then
				count = count + 1;
				if count > player_limit then 
					pc:MovePC(219,-37,-110,13,0);	--boot to Time A
				end
			end
		end
	end
end

-- Kerr_Tiparr (166083) in Hollowshade Moor

function event_spawn(e)
    eq.signal(166257, 101) -- checks with event controller upon spawn
    quests = true;
end

function event_say(e)
    if(e.message:findi("Hail")) then
        e.self:Say("Welcome to our humble outpost, traveller. Let me know if you see anything you need. I consider it an honor to sell here, for doing so enables Vah Shir in training to stay in the field.");
    end
end

function event_signal(e)
    if e.signal == 99 and e.self:GetX() < 2200 then -- abandon fort if inside
        e.self:SetRunning(true);
        eq.start(99);
        quests = false;
    elseif e.signal == 100 and e.self:GetX() > 2200 then -- return to fort if outside
        eq.start(100);
    end
end

function event_waypoint_arrive(e)
    if e.wp >= 5 and e.self:GetGrid() == 99 then -- reached safe spot at ZL, set up in position
        eq.stop();
        e.self:SetRunning(false);
        eq.move_to(2722, 1172, 135, 220, true);
    elseif e.wp >= 5 and e.self:GetGrid() == 100 then -- return trip finished, set up at spawn point
        eq.stop();
        eq.move_to(e.self:GetSpawnPointX(), e.self:GetSpawnPointY(), e.self:GetSpawnPointZ(), e.self:GetSpawnPointH(), true);
        quests = true;
    end
end

function event_trade(e)
    local item_lib = require("items");

    if quests then
        if(item_lib.check_turn_in(e.trade, {item1 = 5566})) then -- Pot of Spicy Fish Stew
            e.self:Say("Thanks " .. e.other:GetName() .. "! That was delicious. Here is the empty bowl.");
            e.other:QuestReward(e.self,0,0,4,0,5567); -- Empty Stew Bowl
        end
    else
        e.self:Say("Apologies my friend, this will have to wait until we are able to return to the fort.");
    end

    item_lib.return_items(e.self, e.other, e.trade)
end

